3	namespace App\Services\Cache;
4	
5	use Closure;
6	use DateTimeInterface;
7	use Illuminate\Contracts\Cache\LockTimeoutException;
8	use Illuminate\Support\Facades\Cache;
9	use Throwable;
10	
11	/**
12	 * Single-flight cache regeneration helper with jitter and stale-while-revalidate.
13	 *
14	 * Wraps Laravel's Cache::remember with a Cache::lock so that under concurrent
15	 * load only one request rebuilds an expired value while others wait and read
16	 * the freshly-filled cache. Models the proven pattern in
17	 * SiteCacheService::getPublicSitePayload.
18	 *
19	 * Use this for any cached value that:
20	 *   - is hot (likely to be requested concurrently when it expires), AND
21	 *   - is expensive to regenerate (multiple DB queries, joins, external calls).
22	 *
23	 * Two methods, depending on whether the closure can return null:
24	 *   - rememberLocked()         — closures that always return a non-null value
25	 *   - rememberLockedNullable() — closures that can return null (e.g. lookups that
26	 *                                may not find a row); uses a sentinel so cached
27	 *                                nulls survive across requests instead of triggering
28	 *                                a fresh DB hit each time.
29	 *
30	 * Cache hardening features (rememberLocked only):
31	 *   - TTL jitter ±20% on every int TTL write, preventing thundering-herd expiry.
32	 *   - Stale-while-revalidate (SWR): stores a long-lived stale copy alongside the
33	 *     primary key. On stale (primary expired, stale present), returns last-good
34	 *     immediately without blocking. The next caller that acquires the lock will
35	 *     recompute and fill the primary key for all subsequent readers.
36	 *   - Lock keys live on the 'cache_locks' Redis DB (via lock_connection in
37	 *     config/cache.php) so Cache::flush() on the data DB never releases held locks.
38	 */
39	class CacheLockService
40	{
41	    /**
42	     * Sentinel cached by rememberLockedNullable when a closure returns null,
43	     * so the cache layer can distinguish "key absent" from "computed, was null".
44	     * Chosen as an unlikely-to-collide string rather than a constant object so
45	     * it survives Redis (de)serialisation cleanly.
46	     */
47	    private const NULL_SENTINEL = '__cache_lock_null_sentinel__';
48	
49	    /**
50	     * Multiplier applied to int TTLs to derive the stale-extension TTL.
51	     * A primary TTL of 60s → stale TTL of 600s (10 min last-good window).
52	     */
53	    private const STALE_TTL_MULTIPLIER = 10;
54	
55	    /**
56	     * Get the value at $key, or compute it via $callback under a single-flight lock.
57	     *
58	     * TTL jitter (±20%) is applied to every int $ttl write to spread expiry across
59	     * the fleet. A stale-extension copy at "$key:stale" is written at 10× the base
60	     * TTL; when the primary expires but the stale copy is still live, the last-good
61	     * value is returned immediately and the lock-acquiring caller recomputes silently
62	     * on the next miss (stale-while-revalidate without a background job).
63	     *
64	     * @param  string  $key  Cache key (the lock key is auto-derived as 'lock:'.$key)
65	     * @param  DateTimeInterface|int  $ttl  Same TTL semantics as Cache::remember (DateTime or seconds).
66	     *                                      Defaults to 60s; callers passing explicit TTL still win.
67	     * @param  Closure(): mixed  $callback  Closure that produces the value on miss; must not return null
68	     * @param  int  $lockSeconds  How long the lock is held before auto-expiring (must exceed worst-case closure runtime)
69	     * @param  int  $blockSeconds  How long a waiting request blocks for the lock before falling through
70	     */
71	    public function rememberLocked(
72	        string $key,
73	        DateTimeInterface|int $ttl,
74	        Closure $callback,
75	        int $lockSeconds = 10,
76	        int $blockSeconds = 5,
77	    ): mixed {
78	        // Fast path: primary key still warm.
79	        $cached = Cache::get($key);
80	        if ($cached !== null) {
81	            return $cached;
82	        }
83	
84	        // SWR fast path: primary expired but stale copy is still live — return
85	        // last-good immediately. The lock below will let one worker recompute.
86	        $staleKey = $key.':stale';
87	        $stale = Cache::get($staleKey);
88	        if ($stale !== null) {
89	            // Try a non-blocking lock attempt so a single worker recomputes in
90	            // this same request. If the lock is already held (another worker is
91	            // recomputing), skip and return the stale value without waiting.
92	            $lock = Cache::lock('lock:'.$key, $lockSeconds);
93	            if ($lock->get()) {
94	                try {
95	                    // Re-check primary after acquiring — another process may have
96	                    // just filled it while we were racing for the lock.
97	                    $fresh = Cache::get($key);
98	                    if ($fresh !== null) {
99	                        return $fresh;
100	                    }
101	
102	                    $value = $callback();
103	                    $this->writeWithJitter($key, $staleKey, $value, $ttl);
104	
105	                    return $value;
106	                } finally {
107	                    try {
108	                        $lock->release();
109	                    } catch (Throwable) {
110	                        // ignore — lock may have auto-expired
111	                    }
112	                }
113	            }
114	
115	            // Another worker is refreshing — return last-good without blocking.
116	            return $stale;
117	        }
118	
119	        // Cold miss — acquire blocking lock so only one worker runs the callback.
120	        $lock = Cache::lock('lock:'.$key, $lockSeconds);
121	
122	        try {
123	            $lock->block($blockSeconds);
124	        } catch (LockTimeoutException) {
125	            // Another process is filling the cache but took too long.
126	            // Return whatever is now cached, or fall through to compute as a last resort
127	            // so the user never gets nothing back. The stampede risk on this edge case
128	            // is bounded to requests that arrive in the timeout window.
129	            $warm = Cache::get($key);
130	            if ($warm !== null) {
131	                return $warm;
132	            }
133	
134	            return $callback();
135	        }
136	
137	        try {
138	            // Double-check: another process may have filled the cache while we waited.
139	            $rechecked = Cache::get($key);
140	            if ($rechecked !== null) {
141	                return $rechecked;
142	            }
143	
144	            $value = $callback();
145	            $this->writeWithJitter($key, $staleKey, $value, $ttl);
146	
147	            return $value;
148	        } finally {
149	            // Always release — even if the closure threw — so we don't hold the lock
150	            // for its full TTL after a failure.
151	            try {
152	                $lock->release();
153	            } catch (Throwable) {
154	                // Lock already released or driver doesn't support release-after-expiry; ignore.
155	            }
156	        }
157	    }
158	
159	    /**
160	     * Write $value to $key with jitter and to $staleKey with the stale extension TTL.
161	     *
162	     * Jitter is applied only to int TTLs (±20% uniform distribution). DateTimeInterface
163	     * TTLs represent a caller-specified deadline and must not be modified.
164	     */
165	    private function writeWithJitter(string $key, string $staleKey, mixed $value, DateTimeInterface|int $ttl): void
166	    {
167	        if ($ttl instanceof DateTimeInterface) {
168	            // Caller wants a specific expiry deadline — honour it exactly.
169	            Cache::put($key, $value, $ttl);
170	            // Stale extension: seconds from now to deadline, then ×10. Ensures
171	            // the stale copy outlives the primary by a meaningful window.
172	            $secondsUntilDeadline = max(1, $ttl->getTimestamp() - now()->timestamp);
173	            Cache::put($staleKey, $value, $secondsUntilDeadline * self::STALE_TTL_MULTIPLIER);
174	
175	            return;
176	        }
177	
178	        // Apply ±20% jitter: mt_rand(0, 4000) / 10000.0 gives [0.0, 0.4],
179	        // adding 0.8 shifts the range to [0.8, 1.2].
180	        $jitteredTtl = (int) round($ttl * (0.8 + mt_rand(0, 4000) / 10000.0));
181	        $staleTtl = $ttl * self::STALE_TTL_MULTIPLIER;
182	
183	        Cache::put($key, $value, $jitteredTtl);
184	        Cache::put($staleKey, $value, $staleTtl);
185	    }
186	
187	    /**
188	     * Like rememberLocked, but the callback may return null. Null results are cached
189	     * as a sentinel so subsequent reads return null without re-running the callback.
190	     *
191	     * Note: no jitter or SWR here — this method is used for negative-cache lookups
192	     * (profile misses, etc.) where stale last-good semantics don't apply.
193	     *
194	     * @param  string  $key  Cache key
195	     * @param  DateTimeInterface|int  $ttl  TTL for non-null values
196	     * @param  Closure(): mixed  $callback  May return null. Must not return the sentinel string.
197	     * @param  DateTimeInterface|int|null  $nullTtl  TTL when caching a null result.
198	     *                                               Defaults to $ttl when null. For negative-cache use cases, pass an explicit
199	     *                                               shorter duration (e.g. 30s) so a "not found" lookup retries sooner once the
200	     *                                               underlying row may have appeared.
201	     */
202	    public function rememberLockedNullable(
203	        string $key,
204	        DateTimeInterface|int $ttl,
205	        Closure $callback,
206	        DateTimeInterface|int|null $nullTtl = null,
207	        int $lockSeconds = 10,
208	        int $blockSeconds = 5,
209	    ): mixed {
210	        $cached = Cache::get($key);
211	        if ($cached === self::NULL_SENTINEL) {
212	            return null;
213	        }
214	        if ($cached !== null) {
215	            return $cached;
216	        }
217	
218	        $lock = Cache::lock('lock:'.$key, $lockSeconds);
219	
220	        try {
221	            $lock->block($blockSeconds);
222	        } catch (LockTimeoutException) {
223	            $warm = Cache::get($key);
224	            if ($warm === self::NULL_SENTINEL) {
225	                return null;
226	            }
227	            if ($warm !== null) {
228	                return $warm;
229	            }
230	
231	            return $callback();
232	        }
233	
234	        try {
235	            $rechecked = Cache::get($key);
236	            if ($rechecked === self::NULL_SENTINEL) {
237	                return null;
238	            }
239	            if ($rechecked !== null) {
240	                return $rechecked;
241	            }
242	
243	            $value = $callback();
244	            if ($value === self::NULL_SENTINEL) {
245	                throw new \LogicException('Closure returned the cache null sentinel; this value is reserved.');
246	            }
247	            if ($value === null) {
248	                Cache::put($key, self::NULL_SENTINEL, $nullTtl ?? $ttl);
249	            } else {
250	                Cache::put($key, $value, $ttl);
251	            }
252	
253	            return $value;
254	        } finally {
255	            try {
256	                $lock->release();
257	            } catch (Throwable) {
258	                // ignore
259	            }
260	        }
261	    }
262	}
